-- Ownership survives payload eviction so a closed recovery upload cannot revive into sync history
ALTER TABLE upload_reservations ADD COLUMN recovery_operation_id TEXT;
DROP TRIGGER upload_reservations_insert;
DROP TRIGGER upload_reservations_delete;
DROP TRIGGER upload_reservations_update;
ALTER TABLE upload_reservations DROP COLUMN metadata_bytes;
ALTER TABLE upload_reservations ADD COLUMN metadata_bytes INTEGER GENERATED ALWAYS AS (length(CAST(json_array(account_id,upload_id,document_id,revision_id,request_digest,request_json,generation,descriptor_reserve,recovery_operation_id) AS BLOB))) VIRTUAL;
CREATE TRIGGER upload_reservations_insert AFTER INSERT ON upload_reservations BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes),metadata_rows=metadata_rows+1 WHERE scope='global' OR scope=NEW.account_id; END;
CREATE TRIGGER upload_reservations_delete AFTER DELETE ON upload_reservations BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (OLD.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(-OLD.metadata_bytes),metadata_rows=metadata_rows-1 WHERE scope='global' OR scope=OLD.account_id; END;
CREATE TRIGGER upload_reservations_update AFTER UPDATE ON upload_reservations BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes-OLD.metadata_bytes),metadata_rows=metadata_rows+0 WHERE scope='global' OR scope=NEW.account_id; END;
-- Appending ownership adds a comma and JSON null to each existing encoded tuple
UPDATE quota_counters SET metadata_bytes=metadata_bytes+5*(SELECT COUNT(*) FROM upload_reservations WHERE scope='global' OR account_id=scope);
DROP TRIGGER recovery_upload_reservations_insert;
DROP TRIGGER recovery_upload_reservations_delete;
DROP TRIGGER recovery_upload_reservations_update;
DELETE FROM recovery_source_stats WHERE name='upload_reservations';
INSERT INTO recovery_source_stats SELECT 'upload_reservations',COUNT(*),COALESCE(SUM(length(CAST(json_array(account_id,upload_id,document_id,revision_id,request_digest,request_json,generation,descriptor_reserve,recovery_operation_id) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(account_id,upload_id,document_id,revision_id,request_digest,request_json,generation,descriptor_reserve,recovery_operation_id) AS BLOB))),0) FROM upload_reservations;
CREATE TRIGGER recovery_upload_reservations_insert AFTER INSERT ON upload_reservations BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.upload_id,NEW.document_id,NEW.revision_id,NEW.request_digest,NEW.request_json,NEW.generation,NEW.descriptor_reserve,NEW.recovery_operation_id) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.upload_id,NEW.document_id,NEW.revision_id,NEW.request_digest,NEW.request_json,NEW.generation,NEW.descriptor_reserve,NEW.recovery_operation_id) AS BLOB))) WHERE name='upload_reservations'; END;
CREATE TRIGGER recovery_upload_reservations_delete AFTER DELETE ON upload_reservations BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes+(-length(CAST(json_array(OLD.account_id,OLD.upload_id,OLD.document_id,OLD.revision_id,OLD.request_digest,OLD.request_json,OLD.generation,OLD.descriptor_reserve,OLD.recovery_operation_id) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.account_id,OLD.upload_id,OLD.document_id,OLD.revision_id,OLD.request_digest,OLD.request_json,OLD.generation,OLD.descriptor_reserve,OLD.recovery_operation_id) AS BLOB))) WHERE name='upload_reservations'; END;
CREATE TRIGGER recovery_upload_reservations_update AFTER UPDATE ON upload_reservations BEGIN UPDATE recovery_source_stats SET rows=rows+0,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.upload_id,NEW.document_id,NEW.revision_id,NEW.request_digest,NEW.request_json,NEW.generation,NEW.descriptor_reserve,NEW.recovery_operation_id) AS BLOB))-length(CAST(json_array(OLD.account_id,OLD.upload_id,OLD.document_id,OLD.revision_id,OLD.request_digest,OLD.request_json,OLD.generation,OLD.descriptor_reserve,OLD.recovery_operation_id) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.upload_id,NEW.document_id,NEW.revision_id,NEW.request_digest,NEW.request_json,NEW.generation,NEW.descriptor_reserve,NEW.recovery_operation_id) AS BLOB))) WHERE name='upload_reservations'; END;
CREATE INDEX upload_recovery_operation ON upload_reservations(account_id,recovery_operation_id);
CREATE TABLE account_recoveries(account_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','completed')),sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN (0,1)),reserved_bytes INTEGER NOT NULL,admitted_bytes INTEGER NOT NULL,created_at INTEGER NOT NULL,completed_at INTEGER,expires_at INTEGER,binding_json TEXT,mutation_id TEXT,accepted_at INTEGER,PRIMARY KEY(account_id,operation_id),UNIQUE(account_id,mutation_id));
ALTER TABLE account_recoveries ADD COLUMN metadata_bytes INTEGER GENERATED ALWAYS AS (length(CAST(json_array(account_id,operation_id,request_digest,state,sealed,reserved_bytes,admitted_bytes,created_at,completed_at,expires_at,binding_json,mutation_id,accepted_at) AS BLOB))) VIRTUAL;
CREATE TRIGGER account_recoveries_insert AFTER INSERT ON account_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes),metadata_rows=metadata_rows+1 WHERE scope='global' OR scope=NEW.account_id; END;
CREATE TRIGGER account_recoveries_delete AFTER DELETE ON account_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (OLD.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(-OLD.metadata_bytes),metadata_rows=metadata_rows-1 WHERE scope='global' OR scope=OLD.account_id; END;
CREATE TRIGGER account_recoveries_update AFTER UPDATE ON account_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes-OLD.metadata_bytes),metadata_rows=metadata_rows+0 WHERE scope='global' OR scope=NEW.account_id; END;
INSERT INTO recovery_source_stats SELECT 'account_recoveries',COUNT(*),COALESCE(SUM(length(CAST(json_array(account_id,operation_id,request_digest,state,sealed,reserved_bytes,admitted_bytes,created_at,completed_at,expires_at,binding_json,mutation_id,accepted_at) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(account_id,operation_id,request_digest,state,sealed,reserved_bytes,admitted_bytes,created_at,completed_at,expires_at,binding_json,mutation_id,accepted_at) AS BLOB))),0) FROM account_recoveries;
CREATE TRIGGER recovery_account_recoveries_insert AFTER INSERT ON account_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.state,NEW.sealed,NEW.reserved_bytes,NEW.admitted_bytes,NEW.created_at,NEW.completed_at,NEW.expires_at,NEW.binding_json,NEW.mutation_id,NEW.accepted_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.state,NEW.sealed,NEW.reserved_bytes,NEW.admitted_bytes,NEW.created_at,NEW.completed_at,NEW.expires_at,NEW.binding_json,NEW.mutation_id,NEW.accepted_at) AS BLOB))) WHERE name='account_recoveries'; END;
CREATE TRIGGER recovery_freeze_account_recoveries_insert BEFORE INSERT ON account_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_account_recoveries_delete AFTER DELETE ON account_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes+(-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.state,OLD.sealed,OLD.reserved_bytes,OLD.admitted_bytes,OLD.created_at,OLD.completed_at,OLD.expires_at,OLD.binding_json,OLD.mutation_id,OLD.accepted_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.state,OLD.sealed,OLD.reserved_bytes,OLD.admitted_bytes,OLD.created_at,OLD.completed_at,OLD.expires_at,OLD.binding_json,OLD.mutation_id,OLD.accepted_at) AS BLOB))) WHERE name='account_recoveries'; END;
CREATE TRIGGER recovery_freeze_account_recoveries_delete BEFORE DELETE ON account_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_account_recoveries_update AFTER UPDATE ON account_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows+0,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.state,NEW.sealed,NEW.reserved_bytes,NEW.admitted_bytes,NEW.created_at,NEW.completed_at,NEW.expires_at,NEW.binding_json,NEW.mutation_id,NEW.accepted_at) AS BLOB))-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.state,OLD.sealed,OLD.reserved_bytes,OLD.admitted_bytes,OLD.created_at,OLD.completed_at,OLD.expires_at,OLD.binding_json,OLD.mutation_id,OLD.accepted_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.state,NEW.sealed,NEW.reserved_bytes,NEW.admitted_bytes,NEW.created_at,NEW.completed_at,NEW.expires_at,NEW.binding_json,NEW.mutation_id,NEW.accepted_at) AS BLOB))) WHERE name='account_recoveries'; END;
CREATE TRIGGER recovery_freeze_account_recoveries_update BEFORE UPDATE ON account_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE INDEX recovery_expiry ON account_recoveries(state,expires_at,completed_at);
CREATE TABLE recovery_revisions(account_id TEXT NOT NULL,operation_id TEXT NOT NULL,upload_id TEXT NOT NULL,revision_id TEXT NOT NULL,descriptor TEXT NOT NULL,generation TEXT,staging_reserve INTEGER NOT NULL CHECK(staging_reserve>=0),PRIMARY KEY(account_id,upload_id),UNIQUE(account_id,revision_id));
ALTER TABLE recovery_revisions ADD COLUMN metadata_bytes INTEGER GENERATED ALWAYS AS (length(CAST(json_array(account_id,operation_id,upload_id,revision_id,descriptor,generation,staging_reserve) AS BLOB))) VIRTUAL;
CREATE TRIGGER recovery_revisions_insert AFTER INSERT ON recovery_revisions BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes),metadata_rows=metadata_rows+1,reserved_metadata=reserved_metadata+(NEW.staging_reserve) WHERE scope='global' OR scope=NEW.account_id; END;
CREATE TRIGGER recovery_revisions_delete AFTER DELETE ON recovery_revisions BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (OLD.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(-OLD.metadata_bytes),metadata_rows=metadata_rows-1,reserved_metadata=reserved_metadata+(-OLD.staging_reserve) WHERE scope='global' OR scope=OLD.account_id; END;
CREATE TRIGGER recovery_revisions_update AFTER UPDATE ON recovery_revisions BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes-OLD.metadata_bytes),metadata_rows=metadata_rows+0,reserved_metadata=reserved_metadata+(NEW.staging_reserve-OLD.staging_reserve) WHERE scope='global' OR scope=NEW.account_id; END;
INSERT INTO recovery_source_stats SELECT 'recovery_revisions',COUNT(*),COALESCE(SUM(length(CAST(json_array(account_id,operation_id,upload_id,revision_id,descriptor,generation,staging_reserve) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(account_id,operation_id,upload_id,revision_id,descriptor,generation,staging_reserve) AS BLOB))),0) FROM recovery_revisions;
CREATE TRIGGER recovery_recovery_revisions_insert AFTER INSERT ON recovery_revisions BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.upload_id,NEW.revision_id,NEW.descriptor,NEW.generation,NEW.staging_reserve) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.upload_id,NEW.revision_id,NEW.descriptor,NEW.generation,NEW.staging_reserve) AS BLOB))) WHERE name='recovery_revisions'; END;
CREATE TRIGGER recovery_freeze_recovery_revisions_insert BEFORE INSERT ON recovery_revisions WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_recovery_revisions_delete AFTER DELETE ON recovery_revisions BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes+(-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.upload_id,OLD.revision_id,OLD.descriptor,OLD.generation,OLD.staging_reserve) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.upload_id,OLD.revision_id,OLD.descriptor,OLD.generation,OLD.staging_reserve) AS BLOB))) WHERE name='recovery_revisions'; END;
CREATE TRIGGER recovery_freeze_recovery_revisions_delete BEFORE DELETE ON recovery_revisions WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_recovery_revisions_update AFTER UPDATE ON recovery_revisions BEGIN UPDATE recovery_source_stats SET rows=rows+0,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.upload_id,NEW.revision_id,NEW.descriptor,NEW.generation,NEW.staging_reserve) AS BLOB))-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.upload_id,OLD.revision_id,OLD.descriptor,OLD.generation,OLD.staging_reserve) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.upload_id,NEW.revision_id,NEW.descriptor,NEW.generation,NEW.staging_reserve) AS BLOB))) WHERE name='recovery_revisions'; END;
CREATE TRIGGER recovery_freeze_recovery_revisions_update BEFORE UPDATE ON recovery_revisions WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE INDEX recovery_point_revisions ON recovery_revisions(account_id,operation_id);
-- Admission is serialized with insert, including pending preparations
-- Restore reinstalls existing ownership even when an administrator has lowered its account quota
CREATE TRIGGER recovery_admission BEFORE INSERT ON account_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1)='open' AND ((SELECT COUNT(*) FROM account_recoveries WHERE account_id=NEW.account_id)>=3 OR NEW.admitted_bytes+(SELECT COALESCE(SUM(admitted_bytes),0) FROM account_recoveries WHERE account_id=NEW.account_id)>MIN(134217728,(SELECT capacity_bytes FROM accounts WHERE id=NEW.account_id))) BEGIN SELECT RAISE(ABORT,'recovery_capacity'); END;
-- Cancelled operations retain a quota-bounded opaque terminal identity even before their first upload
CREATE TABLE cancelled_recoveries(account_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(account_id,operation_id));
ALTER TABLE cancelled_recoveries ADD COLUMN metadata_bytes INTEGER GENERATED ALWAYS AS (length(CAST(json_array(account_id,operation_id,request_digest,created_at) AS BLOB))) VIRTUAL;
CREATE TRIGGER cancelled_recoveries_insert AFTER INSERT ON cancelled_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes),metadata_rows=metadata_rows+1 WHERE scope='global' OR scope=NEW.account_id; END;
CREATE TRIGGER cancelled_recoveries_delete AFTER DELETE ON cancelled_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (OLD.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(-OLD.metadata_bytes),metadata_rows=metadata_rows-1 WHERE scope='global' OR scope=OLD.account_id; END;
CREATE TRIGGER cancelled_recoveries_update AFTER UPDATE ON cancelled_recoveries BEGIN INSERT OR IGNORE INTO quota_counters(scope) VALUES (NEW.account_id); UPDATE quota_counters SET metadata_bytes=metadata_bytes+(NEW.metadata_bytes-OLD.metadata_bytes),metadata_rows=metadata_rows+0 WHERE scope='global' OR scope=NEW.account_id; END;
INSERT INTO recovery_source_stats SELECT 'cancelled_recoveries',COUNT(*),COALESCE(SUM(length(CAST(json_array(account_id,operation_id,request_digest,created_at) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(account_id,operation_id,request_digest,created_at) AS BLOB))),0) FROM cancelled_recoveries;
CREATE TRIGGER recovery_cancelled_recoveries_insert AFTER INSERT ON cancelled_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.created_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.created_at) AS BLOB))) WHERE name='cancelled_recoveries'; END;
CREATE TRIGGER recovery_freeze_cancelled_recoveries_insert BEFORE INSERT ON cancelled_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_cancelled_recoveries_delete AFTER DELETE ON cancelled_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes+(-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.created_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.created_at) AS BLOB))) WHERE name='cancelled_recoveries'; END;
CREATE TRIGGER recovery_freeze_cancelled_recoveries_delete BEFORE DELETE ON cancelled_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER recovery_cancelled_recoveries_update AFTER UPDATE ON cancelled_recoveries BEGIN UPDATE recovery_source_stats SET rows=rows+0,bytes=bytes+(length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.created_at) AS BLOB))-length(CAST(json_array(OLD.account_id,OLD.operation_id,OLD.request_digest,OLD.created_at) AS BLOB))),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.account_id,NEW.operation_id,NEW.request_digest,NEW.created_at) AS BLOB))) WHERE name='cancelled_recoveries'; END;
CREATE TRIGGER recovery_freeze_cancelled_recoveries_update BEFORE UPDATE ON cancelled_recoveries WHEN (SELECT state FROM recovery_control WHERE id=1) IN ('closed','verified') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
