CREATE TABLE superseded_recoveries(account_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL,successor_operation_id TEXT NOT NULL,successor_mutation_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(account_id,operation_id));
